import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"عہدوں کی تقسیم کا عمومی جدول","description":"","frontmatter":{},"headers":[],"relativePath":"ur/70-纪元划分总表.md","filePath":"ur/70-纪元划分总表.md"}'),l={name:"ur/70-纪元划分总表.md"};function i(h,t,o,n,s,_){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="عہدوں-کی-تقسیم-کا-عمومی-جدول" tabindex="-1">عہدوں کی تقسیم کا عمومی جدول <a class="header-anchor" href="#عہدوں-کی-تقسیم-کا-عمومی-جدول" aria-label="Permalink to &quot;عہدوں کی تقسیم کا عمومی جدول&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>70</td></tr><tr><td>ماڈیول</td><td>تاریخی عہد اور اہم واقعات</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>عہد کی تقسیم، تاریخی دوربندی، چار مرحلے جہت کی بلندی، ٹائم لائن، سنگ میل</td></tr></tbody></table><h2 id="_1-عہدوں-کی-تقسیم-کے-بنیادی-اصول" tabindex="-1">1. عہدوں کی تقسیم کے بنیادی اصول <a class="header-anchor" href="#_1-عہدوں-کی-تقسیم-کے-بنیادی-اصول" aria-label="Permalink to &quot;1. عہدوں کی تقسیم کے بنیادی اصول&quot;">​</a></h2><p>ہینگیوان-ژو کی تاریخی عہدوں کی تقسیم چار مرحلے جہت کی بلندی کے راستے کو بنیادی ڈھانچے کے طور پر لیتی ہے، اور اینکر میکانزم کی ترقی کی حالت کو بنیادی دوربندی کی بنیاد کے طور پر لیتی ہے۔ ہر عہد تہذیب اور کائنات کے درمیان تعلق کی ایک بنیادی تبدیلی سے مطابقت رکھتا ہے؛ عہدوں کے درمیان حدود صوابدیدی وقت کے نقطے نہیں ہیں، بلکہ کائناتی سطح کے اہم واقعات سے نشان زد ہیں۔</p><p>عہدوں کی تقسیم تین اصولوں کی پیروی کرتی ہے:</p><ul><li><strong>جہت کی بلندی کی مطابقت کا اصول</strong>: ہر بڑا عہد چار مرحلے جہت کی بلندی کے راستے میں سے ایک مرحلے سے مطابقت رکھتا ہے، اور عہد کے اندر کے ذیلی ادوار اس مرحلے میں اہم پیش رفت سے مطابقت رکھتے ہیں</li><li><strong>واقعات کی نشاندہی کا اصول</strong>: عہد کے آغاز اور اختتام کے نقطے نمایاں اہم واقعات سے طے ہوتے ہیں، سادہ وقت کی مساوی تقسیم سے نہیں</li><li><strong>تہذیب کی حالت کا اصول</strong>: ہر عہد اس دور میں تہذیب کی بنیادی خصوصیات کے نام پر رکھا جاتا ہے، جو اس وقت کے بنیادی تضاد اور ترقی کی سمت کی عکاسی کرتا ہے |</li></ul><h2 id="_2-ہینگیوان-ژو-کے-تاریخی-عہدوں-کا-عمومی-جدول" tabindex="-1">2. ہینگیوان-ژو کے تاریخی عہدوں کا عمومی جدول <a class="header-anchor" href="#_2-ہینگیوان-ژو-کے-تاریخی-عہدوں-کا-عمومی-جدول" aria-label="Permalink to &quot;2. ہینگیوان-ژو کے تاریخی عہدوں کا عمومی جدول&quot;">​</a></h2><table tabindex="0"><thead><tr><th>عہد نمبر</th><th>عہد کا نام</th><th>متعلقہ جہت کی بلندی کا مرحلہ</th><th>آغاز-اختتام کے نشان زد واقعات</th><th>بنیادی خصوصیات</th></tr></thead><tbody><tr><td>پہلا عہد</td><td>اینکر سے پہلے کا دور</td><td>جہت کی بلندی سے پہلے</td><td>کائنات کی پیدائش→پہلی نسل کے اینکر کی بیداری</td><td>لوٹ مار کی سادھنا غالب، تہذیب کی خرابی اکثر</td></tr><tr><td>دوسرا عہد</td><td>اینکر کی بیداری کا عہد</td><td>حقیقت کی بنیاد کا آغاز</td><td>پہلی نسل کے اینکر کی بیداری→سمبیوسس چارٹر پر دستخط</td><td>اینکر میکانزم قائم، لوٹ مار مخالف فکر کی جڑیں</td></tr><tr><td>تیسرا عہد</td><td>سمبیوسس نظام کے قیام کا دور</td><td>حقیقت کی بنیاد</td><td>سمبیوسس چارٹر پر دستخط→تین سو نظام مکمل طور پر کھلنا</td><td>سمبیوسس نظام لاگو، سماجی تعمیر نو مکمل</td></tr><tr><td>چوتھا عہد</td><td>نظام کھلنے اور چالو کرنے کا عہد</td><td>ٹیکنالوجی بااختیار بنانے کا آغاز</td><td>تین سو نظام کھلنا→20% چالو کرنے کی حکمت عملی مکمل</td><td>سادھنا عام کرنا، قانون کی انجینئرنگ ٹیکنالوجی میں پیش رفت</td></tr><tr><td>پانچواں عہد</td><td>پہلی جہت کی بلندی کا عہد</td><td>ٹیکنالوجی بااختیار بنانا→شعور کا ارتقاء</td><td>پہلی جہت کی بلندی کامیاب→تمام نسلوں کی جمہوریہ قائم</td><td>تہذیب کی جہت کی بلندی کی تصدیق، شعور کے ڈومین انٹرفیس میں پیش رفت</td></tr><tr><td>چھٹا عہد</td><td>تمام نسلوں کی جمہوریہ کا عہد</td><td>شعور کا ارتقاء</td><td>تمام نسلوں کی جمہوریہ قائم→تلواروں کے درمیان تحقیق کا آغاز</td><td>تمام نسلوں کا نظام متحد، اجتماعی شعور کی سمبیوسس</td></tr><tr><td>ساتواں عہد</td><td>تلواروں کے درمیان تحقیق کا عہد</td><td>شعور کا ارتقاء→بین النجومی سمبیوسس</td><td>تلواروں کے درمیان تحقیق کا آغاز→بین النجومی نیٹ ورک کی ابتدائی تعمیر</td><td>تلواروں کی بڑی دریافت، اینکر نیٹ ورک کی توسیع</td></tr><tr><td>آٹھواں عہد</td><td>بین النجومی سمبیوسس کا دور</td><td>بین النجومی سمبیوسس</td><td>بین النجومی نیٹ ورک کی تعمیر→کائنات کی عمومی جہت کی بلندی</td><td>تمام نسلوں کی کائناتی سمبیوسس، کائنات کی جہت کی بلندی جاری</td></tr></tbody></table><h2 id="_3-ہر-عہد-کا-وقتانی-دور-اور-بنیادی-اشاریے" tabindex="-1">3. ہر عہد کا وقتانی دور اور بنیادی اشاریے <a class="header-anchor" href="#_3-ہر-عہد-کا-وقتانی-دور-اور-بنیادی-اشاریے" aria-label="Permalink to &quot;3. ہر عہد کا وقتانی دور اور بنیادی اشاریے&quot;">​</a></h2><p>چونکہ ہینگیوان-ژو متعدد تلواروں پر مشتمل ہے اور مختلف تلواروں میں وقت کی رفتار مختلف ہے، عہدوں کا وقتانی دور مرکزی تلوار کے معیاری وقت پر مبنی ہے:</p><table tabindex="0"><thead><tr><th>عہد</th><th>تخمینی وقتانی دور</th><th>اینکر کوریج کی شرح</th><th>سادھکوں کا تناسب</th><th>سمبیوسس ڈگری کا اشاریہ</th></tr></thead><tbody><tr><td>اینکر سے پہلے کا دور</td><td>نامعلوم (اربوں سال کی ترتیب)</td><td>0%</td><td>&lt;0.01%</td><td>&lt;10</td></tr><tr><td>اینکر کی بیداری کا عہد</td><td>ہزاروں سال</td><td>1%→10%</td><td>0.01%→1%</td><td>10→30</td></tr><tr><td>سمبیوسس نظام کے قیام کا دور</td><td>صدیوں</td><td>10%→40%</td><td>1%→10%</td><td>30→50</td></tr><tr><td>نظام کھلنے اور چالو کرنے کا عہد</td><td>صدیوں</td><td>40%→70%</td><td>10%→30%</td><td>50→70</td></tr><tr><td>پہلی جہت کی بلندی کا عہد</td><td>کئی دہائیاں</td><td>70%→85%</td><td>30%→50%</td><td>70→80</td></tr><tr><td>تمام نسلوں کی جمہوریہ کا عہد</td><td>صدیوں</td><td>85%→95%</td><td>50%→70%</td><td>80→90</td></tr><tr><td>تلواروں کے درمیان تحقیق کا عہد</td><td>ہزاروں سال</td><td>95%→99%</td><td>70%→90%</td><td>90→95</td></tr><tr><td>بین النجومی سمبیوسس کا دور</td><td>جاری</td><td>→100%</td><td>→100%</td><td>→100</td></tr></tbody></table><p>اینکر کوریج کی شرح سے مراد ان تلواروں کے ذیلی علاقوں کا تناسب ہے جہاں اینکر ہارڈویئر تعینات کیا گیا ہے؛ سادھکوں کا تناسب سے مراد رسمی سادھنا نظام سے احاطہ شدہ جانداروں کا تناسب ہے؛ سمبیوسس ڈگری کا اشاریہ تہذیب کی سمبیوسس کی ڈگری کی پیمائش کرنے والا ایک جامع اشاریہ ہے، جس کا زیادہ سے زیادہ اسکور 100 ہے۔</p><h2 id="_4-عہدوں-کے-ارتقاء-کی-اندرونی-منطق" tabindex="-1">4. عہدوں کے ارتقاء کی اندرونی منطق <a class="header-anchor" href="#_4-عہدوں-کے-ارتقاء-کی-اندرونی-منطق" aria-label="Permalink to &quot;4. عہدوں کے ارتقاء کی اندرونی منطق&quot;">​</a></h2><p>ہینگیوان-ژو کے عہدوں کا ارتقاء لکیری وقت کے بہاؤ نہیں ہے، بلکہ ایک سرپل اوپر کی طرف بڑھنے والا ارتقائی عمل ہے۔ ہر عہد پچھلے عہد کی چھوڑی ہوئی بنیادی تضاد کو حل کرتے ہوئے اگلے عہد کے لیے ترقی کے حالات پیدا کرتا ہے:</p><ul><li>اینکر سے پہلے کے دور کی بنیادی تضاد لوٹ مار اور سمبیوسس کے درمیان تضاد ہے، جس کی انتہائیت اینکر کی بیداری کی لازمی طرف لے گئی</li><li>اینکر کی بیداری کے عہد نے &quot;کیا اینکر موجود ہے&quot; کے مسئلے کو حل کیا، لیکن &quot;اینکر کس کے لیے کام کرتا ہے&quot; کے ادارہ جاتی چیلنج کا سامنا کیا</li><li>سمبیوسس نظام کے قیام کے دور نے ادارہ جاتی تعمیر مکمل کی، لیکن سادھنا کے وسائل کی اجارہ داری اب بھی عوام کے ارتقاء کو محدود کرتی ہے</li><li>نظام کھلنے اور چالو کرنے کے عہد نے سادھنا کی اجارہ داری کو توڑا، لیکن انفرادی صلاحیت کی چھلانگ نے نئے اخلاقی اور حفاظتی چیلنجز لائے</li><li>پہلی جہت کی بلندی کے عہد نے جہت کی بلندی کی قابلیت کی تصدیق کی، لیکن ایک واحد تلوار کی جہت کی بلندی کائنات کے عمومی ارتقاء کو آگے بڑھانے کے لیے کافی نہیں تھی</li><li>تمام نسلوں کی جمہوریہ کے عہد نے تہذیب کے نظام کو متحد کیا، لیکن کائنات میں ابھی بہت سے غیر متصل تلوار اور نسلیں موجود ہیں</li><li>تلواروں کے درمیان تحقیق کے عہد نے تہذیب کی حدود کو وسعت دی، لیکن منتشر تلواروں کو زیادہ گہرا بین النجومی کنکشن کی ضرورت ہے</li><li>بین النجومی سمبیوسس کا دور بالآخر کائنات کی عمومی جہت کی بلندی کے حتمی ہدف کی طرف اشارہ کرتا ہے</li></ul><h2 id="_5-موجودہ-عہد-کی-پوزیشن" tabindex="-1">5. موجودہ عہد کی پوزیشن <a class="header-anchor" href="#_5-موجودہ-عہد-کی-پوزیشن" aria-label="Permalink to &quot;5. موجودہ عہد کی پوزیشن&quot;">​</a></h2><p>ہینگیوان-ژو کی موجودہ ترقی کی حالت کے مطابق، تہذیب تیسرے عہد (سمبیوسس نظام کے قیام کا دور) سے چوتھے عہد (نظام کھلنے اور چالو کرنے کا عہد) کی منتقلی کے اہم نقطے پر ہے۔ سمبیوسس نظام بنیادی تلواروں میں لاگو ہو چکا ہے، تین سو نظام کے کھلنے کا کام مکمل طور پر آگے بڑھ رہا ہے، اور 20% چالو کرنے کی حکمت عملی نفاذ کے مرحلے میں داخل ہو گئی ہے۔ قانون کی انجینئرنگ کی تہہ میں کئی بنیادی ٹیکنالوجیز (ضرب پھل کا تخمینہ انجن، خلائی قانون ڈیوائس، کاپی آئینہ کا نظام) لیبارٹری سے بڑے پیمانے پر پیداوار کی طرف منتقل ہو چکی ہیں۔</p><p>اس منتقلی کے دور کا بنیادی کام یہ ہے: اس بات کو یقینی بنانا کہ تین سو نظام کا کھلنا واقعی تمام جانداروں کے لیے فائدہ مند ہے، اور ساتھ ہی 20% چالو کرنے کی حکمت عملی کے ذریعے تلوار کے پہلے گروپ کے اعلیٰ ترین مخلوقات کو تربیت دینا، پہلی جہت کی بلندی کے لیے کافی توانائی اور تجربہ جمع کرنا۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>عہدوں کی تقسیم کا عمومی جدول ہینگیوان-ژو کی تاریخی ارتقاء کو سمجھنے کا میکرو فریم ورک ہے۔ یہ کائنات کی طویل تاریخ کو آٹھ واضح اندرونی منطق والے عہدوں میں سمیٹتا ہے، ہر عہد کائنات کی عمومی جہت کی بلندی کی طرف ایک ضروری سیڑھی ہے۔ بعد کے دستاویزات ہر عہد اور اس کے اندر کے اہم واقعات کی تفصیل سے وضاحت کریں گے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>71-اینکر سے پہلے کا دور</li><li>72-اینکر کی بیداری کا عہد</li><li>76-پہلی جہت کی بلندی کا سنگ میل</li></ul>',22)])])}const c=d(l,[["render",i]]);export{b as __pageData,c as default};
